{"Table":"feedback_bkp","Create Table":"CREATE TABLE `feedback_bkp` (\n  `id` varchar(36) NOT NULL,\n  `owner` varchar(64) NOT NULL,\n  `originalText` text NOT NULL,\n  `predictedIntent` text NOT NULL,\n  `correctedIntent` text DEFAULT NULL,\n  `predictedAccount` text DEFAULT NULL,\n  `correctedAccount` text DEFAULT NULL,\n  `predictedOriginAccount` text DEFAULT NULL,\n  `correctedOriginAccount` text DEFAULT NULL,\n  `predictedDestinyAccount` text DEFAULT NULL,\n  `correctedDestinyAccount` text DEFAULT NULL,\n  `predictedCategory` text NOT NULL,\n  `correctedCategory` text DEFAULT NULL,\n  `predictedValue` decimal(18,2) NOT NULL,\n  `correctedValue` decimal(18,2) DEFAULT NULL,\n  `predictedDate` text NOT NULL,\n  `correctedDate` text DEFAULT NULL,\n  `status` enum('pending','validated','corrected') NOT NULL DEFAULT 'pending',\n  `usedForTraining` tinyint(4) NOT NULL DEFAULT 0,\n  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),\n  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_uca1400_ai_ci"}